interface LabelEditorProps {
  submissionId: UUID;
  currentLabel: string;
  defaultLabel: string;
  readOnly: boolean;
  onSaved: (newLabel: string) => void;
}

function LabelEditor({
  submissionId,
  currentLabel,
  defaultLabel,
  readOnly,
  onSaved,
}: LabelEditorProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft]     = useState(currentLabel || defaultLabel);
  const [saving, setSaving]   = useState(false);
  const [error, setError]     = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  function startEdit() {
    if (readOnly) return;
    setDraft(currentLabel || defaultLabel);
    setEditing(true);
    setTimeout(() => inputRef.current?.focus(), 10);
  }

  async function save() {
    if (!draft.trim() || draft.trim() === (currentLabel || defaultLabel)) {
      setEditing(false);
      return;
    }
    setSaving(true);
    setError(null);
    try {
      const res = await apiFetch(
        `${API}/tasks/submissions/${encodeURIComponent(submissionId)}/label`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ label: draft.trim() }),
        }
      );
      if (!res.ok) {
        const body = await res.json().catch(() => null) as { error?: string } | null;
        throw new Error(body?.error ?? `HTTP ${res.status}`);
      }
      onSaved(draft.trim());
      setEditing(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Save failed");
    } finally {
      setSaving(false);
    }
  }

  if (editing) {
    return (
      <div className="flex items-center gap-2">
        <input
          ref={inputRef}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") save();
            if (e.key === "Escape") setEditing(false);
          }}
          maxLength={200}
          className={cn(
            "flex-1 rounded-md border border-primary/50 bg-background px-3 py-1.5 text-sm font-semibold",
            "focus:outline-none focus:ring-2 focus:ring-ring/40"
          )}
        />
        <Button size="icon-sm" onClick={save} disabled={saving}>
          {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
        </Button>
        <Button size="icon-sm" variant="ghost" onClick={() => setEditing(false)}>
          <X className="h-3.5 w-3.5" />
        </Button>
        {error && <span className="text-xs text-destructive">{error}</span>}
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <h1 className="text-2xl font-bold tracking-tight">
        {currentLabel || defaultLabel}
      </h1>
      {!readOnly && (
        <button
          type="button"
          onClick={startEdit}
          title="Edit exercise label"
          className="rounded-md p-1 text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
        >
          <Edit3 className="h-4 w-4" />
        </button>
      )}
    </div>
  );
}

