"use client";

import { useEffect, useMemo, useState } from "react";

import { apiFetch } from "@/lib/auth";

type Client = {
  id: string;
  name: string;
};

const API_BASE =
  "https://clinical-ai-backend.neuvoteam.workers.dev";

  export default function ClientLanding({
    onSelectClient,
  }: {
    onSelectClient: (
      client: any,
      options?: any
    ) => void | Promise<void>;
  }) {
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [clickedId, setClickedId] = useState<string | null>(null);

  const [search, setSearch] = useState("");

  const [firstName, setFirstName] = useState("");
const [middleName, setMiddleName] = useState("");
const [lastName, setLastName] = useState("");

const [email, setEmail] = useState("");

const [countryCode, setCountryCode] =
  useState("+65");

const [phoneNumber, setPhoneNumber] =
  useState("");

  const [creating, setCreating] = useState(false);

const [showAddClient, setShowAddClient] =
  useState(false);
  const emailRegex =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const isFormValid =
  firstName.trim().length > 0 &&
  lastName.trim().length > 0 &&
  emailRegex.test(email) &&
  /^\d+$/.test(phoneNumber) &&
  phoneNumber.length >= 6;

  const fetchClients = async () => {
    try {
      setLoading(true);

      const res = await apiFetch(
        `${API_BASE}/clients`,
        {
          method: "GET",
          cache: "no-store",
        }
      );

      if (!res.ok) {
        throw new Error(
          `Failed to load clients (${res.status})`
        );
      }

      const data = await res.json();

      const parsed = Array.isArray(data)
        ? data
        : [];

      setClients(parsed);
    } catch (err) {
      console.error(err);
      setClients([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const fetchClient = async (id: string) => {
    try {
      const res = await apiFetch(
        `${API_BASE}/client/${id}`,
        {
          method: "GET",
          cache: "no-store",
        }
      );

      if (!res.ok) {
        throw new Error(
          `Failed to load client (${res.status})`
        );
      }

      return await res.json();
    } catch (err) {
      console.error(err);
      return null;
    }
  };

  const handleClientClick = async (
    client: Client
  ) => {
    setClickedId(client.id);

    const fullClient = await fetchClient(
      client.id
    );

    onSelectClient(fullClient || client);
  };

  const handleCreateClient = async () => {
    if (!firstName.trim()) {
      alert("First name is required");
      return;
    }
    
    if (!lastName.trim()) {
      alert("Last name is required");
      return;
    }
    
    if (!email.trim()) {
      alert("Email is required");
      return;
    }
    
    const emailRegex =
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    
    if (!emailRegex.test(email)) {
      alert("Please enter a valid email");
      return;
    }
    
    if (!phoneNumber.trim()) {
      alert("Phone number is required");
      return;
    }
    if (!/^\d+$/.test(phoneNumber)) {
      alert("Phone number can only contain numbers");
      return;
    }
    
    if (
      phoneNumber.length < 6 ||
      phoneNumber.length > 15
    ) {
      alert(
        "Phone number must be between 6 and 15 digits"
      );
      return;
    }

    try {
      setCreating(true);

      const res = await apiFetch(
        `${API_BASE}/clients`,
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
          },
          body: JSON.stringify({
            first_name: firstName,
            middle_name: middleName,
            last_name: lastName,
            email,
            country_code: countryCode,
            phone_number: phoneNumber,
          }),
        }
      );

      if (!res.ok) {
        throw new Error(
