// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

export type TaskVariant = "activity_log" | "thought_record" | "two_choice_worksheet";

interface DynamicTaskFormProps {
  /** Identifies the owning client for the submission. */
  clientId?: UUID;
  /** Practitioner to attribute the submission to. */
  practitionerId?: UUID;
  /** Which handout to render. */
  taskType: TaskVariant;
  /** Optional existing submissionId — pass when resuming a saved draft. */
  initialSubmissionId?: UUID;
  /** Optional submissionId alias matching initialSubmissionId. */
  submissionId?: string | null;
  /** Pre-populated task payload from the AI generator. */
  initialData?: any;
  /** Called after a successful final commit. */
  onSubmitted?: (submission: NormalisedSubmission) => void;
  /** Called when the user cancels. */
  onCancel?: () => void;
  /**
   * Defaults to `true`. When `false` the form is fill-in only: no auto-save,
   * no save badge, no submission id required to navigate, and no
   * "Submit for review" — nothing is sent anywhere.
   */
  persist?: boolean;
}

type SaveStatus = "idle" | "saving" | "saved" | "error";

// ---------------------------------------------------------------------------
// Save-status indicator
// ---------------------------------------------------------------------------
function SaveStatusBadge({ status }: { status: SaveStatus }) {
  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium transition-all",
        status === "idle" && "text-muted-foreground",
        status === "saving" && "bg-amber-100 text-amber-700 dark:bg-amber-950/40 dark:text-amber-300",
        status === "saved" && "bg-emerald-100 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300",
        status === "error" && "bg-rose-100 text-rose-700 dark:bg-rose-950/40 dark:text-rose-300"
      )}
    >
      {status === "idle" && <Cloud className="h-3.5 w-3.5" />}
      {status === "saving" && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
      {status === "saved" && <CheckCircle2 className="h-3.5 w-3.5" />}
      {status === "error" && <CloudOff className="h-3.5 w-3.5" />}

      {status === "idle" && <span>Draft</span>}
      {status === "saving" && <span>Saving…</span>}
      {status === "saved" && <span>Saved</span>}
      {status === "error" && <span>Save failed</span>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Error banner (blocks progression)
// ---------------------------------------------------------------------------
interface ErrorBannerProps {
  message: string;
  onRetry: () => void;
  isRetrying: boolean;
}

function ErrorBanner({ message, onRetry, isRetrying }: ErrorBannerProps) {
  return (
    <div
      role="alert"
      aria-live="assertive"
      className="flex flex-col gap-3 rounded-xl border border-rose-200 bg-rose-50 p-4 dark:border-rose-900 dark:bg-rose-950/40 sm:flex-row sm:items-center sm:justify-between"
    >
      <div className="flex items-start gap-3">
        <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-rose-600 dark:text-rose-400" />
        <div>
          <p className="text-sm font-semibold text-rose-800 dark:text-rose-200">
            Auto-save failed — your progress is not saved
          </p>
          <p className="mt-0.5 text-xs text-rose-700/80 dark:text-rose-300/80">
            {message}
          </p>
          <p className="mt-1 text-xs text-rose-700/80 dark:text-rose-300/80">
            Form progression is paused until the connection is restored. Do not
            close this tab.
          </p>
        </div>
      </div>
      <Button
        variant="outline"
        size="sm"
        onClick={onRetry}
        disabled={isRetrying}
        className="shrink-0 border-rose-300 text-rose-700 hover:bg-rose-100 dark:border-rose-800 dark:text-rose-300 dark:hover:bg-rose-900"
      >
        {isRetrying ? (
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
        ) : (
          "Retry now"
        )}
      </Button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Human-approval gate (shown before final submit)
// ---------------------------------------------------------------------------
interface ApprovalGateProps {
  onConfirm: () => void;
  onCancel: () => void;
  isSubmitting: boolean;
}

function ApprovalGate({ onConfirm, onCancel, isSubmitting }: ApprovalGateProps) {
  const [agreed, setAgreed] = useState(false);

  return (
    <div className="rounded-xl border border-primary/30 bg-primary/5 p-6 space-y-4">
      <div className="flex items-center gap-3">
        <ShieldCheck className="h-6 w-6 text-primary shrink-0" />
        <div>
          <h3 className="text-base font-semibold">Ready to submit for review?</h3>
          <p className="text-sm text-muted-foreground mt-0.5">
            Your completed task will be sent to your practitioner for review.
            You won&apos;t be able to edit it after submission.
          </p>
        </div>
      </div>

      <label className="flex items-start gap-3 cursor-pointer">
        <input
          type="checkbox"
          checked={agreed}
          onChange={(e) => setAgreed(e.target.checked)}
          className="mt-0.5 h-4 w-4 rounded-xs border-input accent-primary"
        />
        <span className="text-sm text-foreground">
          I confirm this is my completed work and I&apos;m ready for my
          practitioner to review it.
        </span>
      </label>

      <div className="flex gap-3">
        <Button
          variant="outline"
          size="sm"
          onClick={onCancel}
          disabled={isSubmitting}
          className="flex-1 sm:flex-none"
        >
          Go back
        </Button>
        <Button
          size="sm"
          onClick={onConfirm}
          disabled={!agreed || isSubmitting}
          className="flex-1 sm:flex-none gap-2"
        >
          {isSubmitting ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Send className="h-4 w-4" />
          )}
          Submit for review
        </Button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step-wizard shell for activity_log
// (The schedule is one big form; we split it into 3 "days" pages to avoid
// cognitive overload — Mon–Tue, Wed–Thu, Fri–Sun.)
// ---------------------------------------------------------------------------
const ACTIVITY_STEPS = [
  { label: "Mon – Tue", days: ["Mon", "Tue"] as const },
  { label: "Wed – Thu", days: ["Wed", "Thu"] as const },
  { label: "Fri – Sun", days: ["Fri", "Sat", "Sun"] as const },
];

// ---------------------------------------------------------------------------
// DynamicTaskForm (main export)
// ---------------------------------------------------------------------------
export function DynamicTaskForm({
  clientId = "",
  practitionerId = "00000000-0000-0000-0000-000000000000",
  taskType,
  initialSubmissionId,
  submissionId: externalSubmissionId,
  initialData,
  onSubmitted,
  onCancel,
  persist = true,
}: DynamicTaskFormProps) {

  // ── Wizard state ──────────────────────────────────────────────────────────
  const [wizardStep, setWizardStep] = useState(0);
  const totalSteps = taskType === "activity_log" ? ACTIVITY_STEPS.length : 1;

  // ── Form data ─────────────────────────────────────────────────────────────
  const [schedule, setSchedule] = useState<WeeklySchedule>(() => {
    const empty = createEmptySchedule();
    if (initialData?.activity_description) {
      try {
        const parsed = JSON.parse(initialData.activity_description);
        return { ...empty, ...parsed };
      } catch {
        return empty;
      }
    }
    return empty;
  });

  const [threeCsData, setThreeCsData] = useState<ThreeCsData>(() => {
    const empty = createEmptyThreeCsData();
    if (!initialData) return empty;
    return {
      situation: initialData.situation ?? empty.situation,
      automaticThought: initialData.automatic_thought ?? initialData.automaticThought ?? empty.automaticThought,
      emotions: initialData.emotions?.length ? initialData.emotions : empty.emotions,
      evidenceFor: initialData.evidence_for ?? initialData.evidenceFor ?? empty.evidenceFor,
      evidenceAgainst: initialData.evidence_against ?? initialData.evidenceAgainst ?? empty.evidenceAgainst,
      balancedThought: initialData.balanced_thought ?? initialData.balancedThought ?? empty.balancedThought,
      outcomeEmotionIntensity: initialData.outcome_emotion_intensity ?? initialData.outcomeEmotionIntensity ?? empty.outcomeEmotionIntensity,
    };
  });

  const [twoChoiceData, setTwoChoiceData] = useState<TwoChoiceData>(() => {
    const empty = createEmptyTwoChoiceData();
    if (!initialData || taskType !== "two_choice_worksheet") return empty;
    return {
      title: initialData.title ?? empty.title,
      prompts: initialData.prompts ?? empty.prompts,
      answers: initialData.answers ?? initialData.prompts?.map(() => null) ?? empty.answers,
      reflection: initialData.reflection ?? empty.reflection,
      reflection_prompt: initialData.reflection_prompt ?? empty.reflection_prompt,
      notes: initialData.notes ?? empty.notes,
    };
  });

  // ── Persistence state ─────────────────────────────────────────────────────
  const [submissionId, setSubmissionId] = useState<UUID | undefined>(
    initialSubmissionId ?? (externalSubmissionId || undefined)
  );

  useEffect(() => {
    if (externalSubmissionId) {
      setSubmissionId(externalSubmissionId);
    }
  }, [externalSubmissionId]);
  const [saveStatus, setSaveStatus] = useState<SaveStatus>("idle");
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isRetrying, setIsRetrying] = useState(false);

  // ── Commit state ──────────────────────────────────────────────────────────
  const [showApprovalGate, setShowApprovalGate] = useState(false);
  const [, startCommitTransition] = useTransition();
  const [isCommitting, setIsCommitting] = useState(false);
  const [committed, setCommitted] = useState(false);

  // ── Debounce ref ──────────────────────────────────────────────────────────
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ── Build FormData payload from current state ─────────────────────────────
  const buildFormData = useCallback((): FormData => {
    if (taskType === "activity_log") {
      // Flatten WeeklySchedule to ActivityLogFormData for the first
      // non-empty entry as a representative; full grid is stored in notes.
      // Per types/tasks.ts, ActivityLogFormData has a single activity_date.
      // We store the full weekly grid as a JSON string in the notes field.
      const payload: ActivityLogFormData = {
        task_type: "activity_log",
        activity_date: new Date().toISOString().slice(0, 10),
        activity_description: JSON.stringify(schedule),
        pleasure_rating: 5,
        mastery_rating: 5,
        notes: "Weekly activity schedule — see activity_description for grid.",
      };
      return payload;
    } else if (taskType === "thought_record") {
      const payload: ThoughtRecordFormData = {
        task_type: "thought_record",
        situation: threeCsData.situation,
        automatic_thought: threeCsData.automaticThought,
        emotions: threeCsData.emotions.map((e) => ({
          label: e.label,
          intensity: e.intensity,
        })),
        evidence_for: threeCsData.evidenceFor,
        evidence_against: threeCsData.evidenceAgainst,
        balanced_thought: threeCsData.balancedThought,
        outcome_emotion_intensity: threeCsData.outcomeEmotionIntensity,
      };
      return payload;
    } else {
      const payload: TwoChoiceWorksheetFormData = {
        task_type: "two_choice_worksheet",
        title: twoChoiceData.title,
        prompts: twoChoiceData.prompts,
        answers: twoChoiceData.answers,
        reflection: twoChoiceData.reflection,
        reflection_prompt: twoChoiceData.reflection_prompt,
        notes: twoChoiceData.notes,
      };
      return payload;
    }
  }, [taskType, schedule, threeCsData, twoChoiceData]);

  // ── Core save function ────────────────────────────────────────────────────
  const performSave = useCallback(
    async (formData: FormData): Promise<boolean> => {
      // Fill-in-only mode: never touch the network.
      if (!persist) return false;

      setSaveStatus("saving");
      setSaveError(null);

      try {
        const res = await apiFetch(`${CLINICAL_AI_API_BASE}/tasks/submissions`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            id: submissionId ?? null,
            client_id: clientId,
            practitioner_id: practitionerId,
            task_type: taskType,
            form_data: formData,
          }),
        });

        if (!res.ok) {
          const body = await res.json().catch(() => null) as { error?: string } | null;
          throw new Error(body?.error ?? `HTTP ${res.status}`);
        }

        const row = await res.json() as { id: UUID };
        // Persist the returned id so subsequent saves update the same row.
        setSubmissionId((prev) => prev ?? row.id);
        setSaveStatus("saved");
        return true;
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Unknown error";
        setSaveError(msg);
        setSaveStatus("error");
        return false;
      }
    },
    [submissionId, clientId, practitionerId, taskType, persist]
  );

  // ── Debounced auto-save ───────────────────────────────────────────────────
  const triggerAutoSave = useCallback(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    // Mark as pending immediately so the UI reflects unsaved state
    setSaveStatus("saving");
    debounceRef.current = setTimeout(() => {
      performSave(buildFormData());
    }, 1200);
  }, [buildFormData, performSave]);

  // Schedule save whenever data changes
  useEffect(() => {
    if (!persist) return;
    triggerAutoSave();
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [schedule, threeCsData, twoChoiceData]);

  // ── Manual retry ─────────────────────────────────────────────────────────
  const handleRetry = useCallback(async () => {
    setIsRetrying(true);
    await performSave(buildFormData());
    setIsRetrying(false);
  }, [buildFormData, performSave]);

  // ── Navigation guards ─────────────────────────────────────────────────────
  // Without persistence there is no save state to wait on.
  const canProgress = !persist || saveStatus !== "error";
  const isLastStep = wizardStep === totalSteps - 1;

  // ── Final commit ──────────────────────────────────────────────────────────
  const handleCommit = useCallback(() => {
    if (!persist || !submissionId) return;
    setIsCommitting(true);

    startCommitTransition(async () => {
      try {
        const res = await apiFetch(
          `${CLINICAL_AI_API_BASE}/tasks/submissions/${encodeURIComponent(submissionId)}/commit`,
          { method: "POST", headers: { "Content-Type": "application/json" } }
        );

        if (!res.ok) {
          const body = await res.json().catch(() => null) as { error?: string } | null;
          throw new Error(body?.error ?? `HTTP ${res.status}`);
        }

        const submitted = await res.json() as NormalisedSubmission;
        setCommitted(true);
        onSubmitted?.(submitted);
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Submit failed";
        setSaveError(msg);
        setSaveStatus("error");
        setShowApprovalGate(false);
      } finally {
        setIsCommitting(false);
      }
    });
  }, [submissionId, onSubmitted, startCommitTransition, persist]);

  // ── Progress bar ──────────────────────────────────────────────────────────
  const progressValue = useMemo(
    () => Math.round(((wizardStep + 1) / totalSteps) * 100),
    [wizardStep, totalSteps]
  );

  // ── Success screen ────────────────────────────────────────────────────────
  if (committed) {
    return (
      <div className="flex min-h-[50vh] flex-col items-center justify-center gap-6 px-6 py-12 text-center">
        <div className="flex h-20 w-20 items-center justify-center rounded-full bg-emerald-100 dark:bg-emerald-950">
          <CheckCircle2 className="h-10 w-10 text-emerald-600 dark:text-emerald-400" />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-bold">Task submitted!</h2>
          <p className="text-muted-foreground max-w-sm">
            Your practitioner will review your responses and get back to you.
            Great work completing this task.
          </p>
        </div>
        {onCancel && (
          <Button variant="outline" onClick={onCancel} size="lg">
            Return to dashboard
          </Button>
        )}
      </div>
    );
  }

  // ── Task title ────────────────────────────────────────────────────────────
  const taskTitle =
    taskType === "activity_log"
      ? "Weekly Activity Schedule"
      : taskType === "thought_record" 
      ? "The 3 C's Practice Worksheet"
      : "Interactive Worksheet";

  const taskSubtitle =
    taskType === "activity_log"
      ? "Track your activities and mood ratings across the week"
      : taskType === "thought_record"
      ? "Identify, examine, and reframe automatic thoughts"
      : "Make choices and reflect on your task";

  return (
    <div className="mx-auto max-w-4xl space-y-6 px-4 py-6 sm:px-6">

      {/* ── Header ──────────────────────────────────────────── */}
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">{taskTitle}</h1>
            <p className="text-sm text-muted-foreground">{taskSubtitle}</p>
          </div>
          {persist && <SaveStatusBadge status={saveStatus} />}
        </div>

        {/* Progress bar */}
        {totalSteps > 1 && (
          <div className="space-y-1 pt-2">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span>{ACTIVITY_STEPS[wizardStep].label}</span>
              <span>
                {wizardStep + 1} / {totalSteps}
              </span>
            </div>
            <Progress value={progressValue} className="h-1.5" />
          </div>
        )}
      </div>

      {/* ── Save-error banner (blocks progression) ─────────── */}
      {saveStatus === "error" && saveError && (
        <ErrorBanner
          message={saveError}
          onRetry={handleRetry}
          isRetrying={isRetrying}
        />
      )}

      {/* ── Form body ────────────────────────────────────────── */}
      <div className="min-h-[400px]">
        {taskType === "activity_log" && (
          <ActivityScheduleForm
            schedule={schedule}
            onChange={setSchedule}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}

        {taskType === "thought_record" && (
          <ThreeCsForm
            data={threeCsData}
            onChange={setThreeCsData}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}

        {taskType === "two_choice_worksheet" && (
          <TwoChoiceWorksheetForm
            data={twoChoiceData}
            onChange={setTwoChoiceData}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}
      </div>

      {/* ── Approval gate ────────────────────────────────────── */}
      {showApprovalGate && (
        <ApprovalGate
          onConfirm={handleCommit}
          onCancel={() => setShowApprovalGate(false)}
          isSubmitting={isCommitting}
        />
      )}

      {/* ── Navigation row ───────────────────────────────────── */}
      {!showApprovalGate && (
        <div className="flex items-center justify-between border-t border-border pt-4">
          {!persist && wizardStep === 0 && !onCancel ? (
            // Fill-in-only with no cancel handler: a "Cancel" would do nothing.
            <span aria-hidden="true" />
          ) : (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                if (wizardStep > 0) {
                  setWizardStep((s) => s - 1);
                } else {
                  onCancel?.();
                }
              }}
              className="gap-1.5"
            >
              <ChevronLeft className="h-4 w-4" />
              {wizardStep === 0 ? "Cancel" : "Back"}
            </Button>
          )}

          <div className="flex items-center gap-2">
            {/* Dot pagination (multi-step only) */}
            {totalSteps > 1 &&
              Array.from({ length: totalSteps }, (_, i) => (
                <span
                  key={i}
                  className={cn(
                    "h-1.5 rounded-full transition-all",
                    i === wizardStep
                      ? "w-5 bg-primary"
                      : "w-1.5 bg-muted-foreground/30"
                  )}
                />
              ))}
          </div>

          {isLastStep && !persist ? (
            // Fill-in-only: there is nothing to submit, so say so plainly.
            <p className="text-xs text-muted-foreground text-right">
              Answers on this page are not saved or sent.
            </p>
          ) : isLastStep ? (
            <Button
              size="sm"
              disabled={
                saveStatus === "error" ||
                saveStatus === "saving" ||
                !submissionId
              }
              onClick={() => setShowApprovalGate(true)}
              className="gap-1.5"
              title={
                !submissionId
                  ? "Waiting for first auto-save…"
                  : saveStatus === "error"
                  ? "Resolve save error before submitting"
                  : undefined
              }
            >
              <Send className="h-4 w-4" />
              Submit for review
            </Button>
          ) : (
            <Button
              size="sm"
              disabled={!canProgress}
              onClick={() => setWizardStep((s) => Math.min(s + 1, totalSteps - 1))}
              className="gap-1.5"
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * components/tasks/ThreeCsForm.tsx
 *
 * Handout 10 — "The 3 C's Practice Worksheet"
 *
 * Three sequential steps with Typeform-style progressive disclosure:
 *   Step 1 — Catch It   (notice the automatic thought)
 *   Step 2 — Check It   (examine the evidence)
 *   Step 3 — Correct It (craft a balanced thought)
 *
 * Each step is revealed only once the previous one has content, so the user
 * is never overwhelmed by a dense wall of fields.
 *
 * Data shape maps to ThoughtRecordFormData (types/tasks.ts).
 */

import React, { useMemo } from "react";
import { cn } from "@/lib/utils";
import { Check, Lock } from "lucide-react";
import { Slider } from "@/components/ui/slider";
import { Textarea } from "@/components/ui/textarea";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ThreeCsData {
  // Step 1 — Catch It
  situation: string;
  automaticThought: string;
  emotions: Array<{ label: string; intensity: number }>;
  // Step 2 — Check It
  evidenceFor: string;
  evidenceAgainst: string;
  // Step 3 — Correct It
  balancedThought: string;
  outcomeEmotionIntensity: number; // 0-100
}

export function createEmptyThreeCsData(): ThreeCsData {
  return {
    situation: "",
    automaticThought: "",
    emotions: [{ label: "", intensity: 50 }],
    evidenceFor: "",
    evidenceAgainst: "",
    balancedThought: "",
    outcomeEmotionIntensity: 50,
  };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const COMMON_EMOTIONS = [
  "Anxious", "Sad", "Angry", "Hopeless", "Guilty",
  "Embarrassed", "Frustrated", "Lonely", "Ashamed", "Worried",
];

function intensityLabel(v: number): string {
  if (v >= 80) return "Very high";
  if (v >= 60) return "High";
  if (v >= 40) return "Moderate";
  if (v >= 20) return "Low";
  return "Very low";
}

function intensityColor(v: number): string {
  if (v >= 80) return "text-rose-600 dark:text-rose-400";
  if (v >= 60) return "text-amber-600 dark:text-amber-400";
  if (v >= 40) return "text-yellow-600 dark:text-yellow-400";
  return "text-emerald-600 dark:text-emerald-400";
}

// ---------------------------------------------------------------------------
// StepCard  — progressive-disclosure wrapper
// ---------------------------------------------------------------------------
interface StepCardProps {
  step: 1 | 2 | 3;
  label: string;
  icon: string;
  colour: string;
  isActive: boolean;
  isComplete: boolean;
  isLocked: boolean;
  children: React.ReactNode;
}

function StepCard({
  step,
  label,
  icon,
  colour,
  isActive,
  isComplete,
  isLocked,
  children,
}: StepCardProps) {
  return (
    <div
      className={cn(
        "rounded-xl border transition-all duration-300",
        isLocked
          ? "border-border/40 opacity-50"
          : isActive
          ? "border-primary/40 shadow-md shadow-primary/5"
          : "border-border"
      )}
    >
      {/* Header */}
      <div
        className={cn(
          "flex items-center gap-3 px-5 py-4 rounded-t-xl",
          colour
        )}
      >
        <div
          className={cn(
            "flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-sm font-bold",
            isComplete
              ? "bg-emerald-500 text-white"
              : isLocked
              ? "bg-muted text-muted-foreground"
              : "bg-primary text-primary-foreground"
          )}
        >
          {isComplete ? <Check className="h-4 w-4" /> : isLocked ? <Lock className="h-3.5 w-3.5" /> : step}
        </div>
        <div>
          <p className="text-[10px] font-medium uppercase tracking-wider opacity-70">
            Step {step} of 3
          </p>
          <p className="text-base font-semibold leading-tight">
            {icon} {label}
          </p>
        </div>
      </div>

      {/* Body */}
      {!isLocked && (
        <div className="px-5 pb-5 pt-4 space-y-5">{children}</div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// EmotionRow
// ---------------------------------------------------------------------------
interface EmotionRowProps {
  emotion: { label: string; intensity: number };
  onChange: (e: { label: string; intensity: number }) => void;
  onRemove: () => void;
  canRemove: boolean;
  disabled?: boolean;
}

function EmotionRow({ emotion, onChange, onRemove, canRemove, disabled }: EmotionRowProps) {
  return (
    <div className="space-y-2 rounded-xl border border-border/60 bg-muted/30 p-3">
      {/* Emotion name */}
      <div className="flex items-center gap-2">
        <select
          value={COMMON_EMOTIONS.includes(emotion.label) ? emotion.label : "__custom__"}
          onChange={(e) =>
            onChange({
              ...emotion,
              label: e.target.value === "__custom__" ? "" : e.target.value,
            })
          }
          disabled={disabled}
          className={cn(
            "flex-1 rounded-md border border-input bg-background px-3 py-2 text-sm",
            "focus:outline-none focus:ring-2 focus:ring-ring/40"
          )}
        >
          <option value="">— Select emotion —</option>
          {COMMON_EMOTIONS.map((e) => (
            <option key={e} value={e}>
              {e}
            </option>
          ))}
          <option value="__custom__">Other…</option>
        </select>
        {canRemove && (
          <button
            type="button"
            onClick={onRemove}
            disabled={disabled}
            className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors"
          >
            ×
          </button>
        )}
      </div>

      {/* Custom label */}
      {!COMMON_EMOTIONS.includes(emotion.label) && (
        <input
          type="text"
          value={emotion.label}
          onChange={(e) => onChange({ ...emotion, label: e.target.value })}
          placeholder="Describe the emotion…"
          disabled={disabled}
          className={cn(
            "w-full rounded-md border border-input bg-background px-3 py-2 text-sm",
            "focus:outline-none focus:ring-2 focus:ring-ring/40"
          )}
        />
      )}

      {/* Intensity slider */}
      <div className="flex items-center gap-3">
        <span className="text-xs text-muted-foreground whitespace-nowrap w-14">
          Intensity
        </span>
        <Slider
          min={0}
          max={100}
          step={5}
          value={[emotion.intensity]}
          onValueChange={([v]) => onChange({ ...emotion, intensity: v })}
          disabled={disabled}
          className="flex-1"
        />
        <span className={cn("text-xs font-semibold w-20 text-right", intensityColor(emotion.intensity))}>
          {emotion.intensity}% · {intensityLabel(emotion.intensity)}
        </span>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// ThreeCsForm  — exported component
// ---------------------------------------------------------------------------
interface ThreeCsFormProps {
  data: ThreeCsData;
  onChange: (data: ThreeCsData) => void;
  disabled?: boolean;
}

export function ThreeCsForm({ data, onChange, disabled }: ThreeCsFormProps) {
  const step1Complete = useMemo(
    () =>
      data.situation.trim().length > 0 &&
      data.automaticThought.trim().length > 0 &&
      data.emotions.some((e) => e.label.trim().length > 0),
    [data]
  );

  const step2Complete = useMemo(
    () =>
      step1Complete &&
      data.evidenceFor.trim().length > 0 &&
      data.evidenceAgainst.trim().length > 0,
    [step1Complete, data]
  );

  function updateEmotion(index: number, emotion: { label: string; intensity: number }) {
    const updated = [...data.emotions];
    updated[index] = emotion;
    onChange({ ...data, emotions: updated });
  }

  function addEmotion() {
    onChange({ ...data, emotions: [...data.emotions, { label: "", intensity: 50 }] });
  }

  function removeEmotion(index: number) {
    onChange({ ...data, emotions: data.emotions.filter((_, i) => i !== index) });
  }

  return (
    <div className="space-y-4">

      {/* ── Step 1: Catch It ───────────────────────────────── */}
      <StepCard
        step={1}
        label="Catch It"
        icon="🎯"
        colour="bg-violet-50/70 dark:bg-violet-950/30 text-violet-900 dark:text-violet-100"
        isActive={!step1Complete}
        isComplete={step1Complete}
        isLocked={false}
      >
        <div className="space-y-1.5">
          <label className="text-sm font-medium">
            Describe the situation
            <span className="text-destructive ml-0.5">*</span>
          </label>
          <p className="text-xs text-muted-foreground">
            Where were you? What were you doing? Who was there?
          </p>
          <Textarea
            value={data.situation}
            onChange={(e) => onChange({ ...data, situation: e.target.value })}
            placeholder="e.g. I was at a team meeting when my manager asked for feedback…"
            rows={3}
            disabled={disabled}
            className="resize-none"
          />
        </div>

        <div className="space-y-1.5">
          <label className="text-sm font-medium">
            What was the automatic thought that crossed your mind?
            <span className="text-destructive ml-0.5">*</span>
          </label>
          <p className="text-xs text-muted-foreground">
            Write it exactly as it appeared — don't edit or censor it.
          </p>
          <Textarea
            value={data.automaticThought}
            onChange={(e) => onChange({ ...data, automaticThought: e.target.value })}
            placeholder={`e.g. "Everyone thinks I'm incompetent."`}
            rows={2}
            disabled={disabled}
            className="resize-none"
          />
        </div>

        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <label className="text-sm font-medium">
              Emotions &amp; intensity
              <span className="text-destructive ml-0.5">*</span>
            </label>
            <button
              type="button"
              onClick={addEmotion}
              disabled={disabled}
              className={cn(
                "rounded-md px-3 py-1 text-xs font-medium text-primary",
                "border border-primary/40 hover:bg-primary/10 transition-colors"
              )}
            >
              + Add emotion
            </button>
          </div>
          {data.emotions.map((emotion, i) => (
            <EmotionRow
              key={i}
              emotion={emotion}
              onChange={(e) => updateEmotion(i, e)}
              onRemove={() => removeEmotion(i)}
              canRemove={data.emotions.length > 1}
              disabled={disabled}
            />
          ))}
        </div>
      </StepCard>

      {/* ── Step 2: Check It ───────────────────────────────── */}
      <StepCard
        step={2}
        label="Check It"
        icon="🔍"
        colour="bg-amber-50/70 dark:bg-amber-950/30 text-amber-900 dark:text-amber-100"
        isActive={step1Complete && !step2Complete}
        isComplete={step2Complete}
        isLocked={!step1Complete}
      >
        <div className="space-y-1.5">
          <label className="text-sm font-medium">
            Evidence that supports the thought
            <span className="text-destructive ml-0.5">*</span>
          </label>
          <p className="text-xs text-muted-foreground">
            Stick to observable facts — not interpretations.
          </p>
          <Textarea
            value={data.evidenceFor}
            onChange={(e) => onChange({ ...data, evidenceFor: e.target.value })}
            placeholder="e.g. My manager pointed out a mistake in my report."
            rows={3}
            disabled={disabled}
            className="resize-none"
          />
        </div>

        <div className="space-y-1.5">
          <label className="text-sm font-medium">
            Evidence that doesn&apos;t support the thought
            <span className="text-destructive ml-0.5">*</span>
          </label>
          <p className="text-xs text-muted-foreground">
            What facts challenge or contradict the thought?
          </p>
          <Textarea
            value={data.evidenceAgainst}
            onChange={(e) => onChange({ ...data, evidenceAgainst: e.target.value })}
            placeholder="e.g. My manager praised my presentation last week."
            rows={3}
            disabled={disabled}
            className="resize-none"
          />
        </div>
      </StepCard>

      {/* ── Step 3: Correct It ─────────────────────────────── */}
      <StepCard
        step={3}
        label="Correct It"
        icon="✨"
        colour="bg-emerald-50/70 dark:bg-emerald-950/30 text-emerald-900 dark:text-emerald-100"
        isActive={step2Complete}
        isComplete={false}
        isLocked={!step2Complete}
      >
        <div className="space-y-1.5">
          <label className="text-sm font-medium">
            Balanced, realistic thought
            <span className="text-destructive ml-0.5">*</span>
          </label>
          <p className="text-xs text-muted-foreground">
            Using both sets of evidence, write a more balanced perspective.
          </p>
          <Textarea
            value={data.balancedThought}
            onChange={(e) => onChange({ ...data, balancedThought: e.target.value })}
            placeholder={`e.g. "I made one mistake, but I've also received positive feedback. I'm still learning."`}
            rows={3}
            disabled={disabled}
            className="resize-none"
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-medium">
            How intense is the original emotion now?
          </label>
          <div className="flex items-center gap-3">
            <Slider
              min={0}
              max={100}
              step={5}
              value={[data.outcomeEmotionIntensity]}
              onValueChange={([v]) => onChange({ ...data, outcomeEmotionIntensity: v })}
              disabled={disabled}
              className="flex-1"
            />
            <span className={cn("text-sm font-bold w-24 text-right tabular-nums", intensityColor(data.outcomeEmotionIntensity))}>
              {data.outcomeEmotionIntensity}% · {intensityLabel(data.outcomeEmotionIntensity)}
            </span>
          </div>
          <p className="text-[11px] text-muted-foreground">
            It&apos;s normal for this to remain above 0 — the goal is reduction, not elimination.
          </p>
        </div>
      </StepCard>
    </div>
  );
}

